const UsersList = () => {
  // ** Store Vars
  const dispatch = useDispatch()
  const store = useSelector(state => state.users)

  // ** States
  const [sort, setSort] = useState('desc')
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const [sortColumn, setSortColumn] = useState('id')
  const [rowsPerPage, setRowsPerPage] = useState(10)
  const [sidebarOpen, setSidebarOpen] = useState(false)
  // const [currentRole, setCurrentRole] = useState({ value: '4', label: 'Select Role' })
  // const currentRole = { value: '4', label: 'Buyer' }
  // const [currentPlan, setCurrentPlan] = useState({ value: '', label: 'Select Plan' })
  // const [currentStatus, setCurrentStatus] = useState({ value: '', label: 'Select Status', number: 0 })
  const currentStatus = { value: null, label: 'Select Status', number: 0 }
  const [loading, setLoading] = useState(false)

  // ** Function to toggle sidebar
  const toggleSidebar = () => setSidebarOpen(!sidebarOpen)

  // ** Get data on mount
  useEffect(() => {
    setLoading(true)
    dispatch(getAllData())
    dispatch(getData({
      order_by: sortColumn.concat(' ', sort.toUpperCase()),
      search: searchTerm,
      skip: (currentPage - 1) * rowsPerPage,
      limit: rowsPerPage,
      expand_reward: true,
      expand_agency: true,
      expand_campaign: true,
      used: true
    })).then(() => setLoading(false))
  }, [dispatch])
  // useEffect(() => {
  //   console.log(store)
  // }, [store])

  // ** User filter options
  // const roleOptions = [
  //   { value: '', label: 'Select Role' },
  //   { value: 'admin', label: 'Admin' },
  //   { value: 'author', label: 'Author' },
  //   { value: 'editor', label: 'Editor' },
  //   { value: 'maintainer', label: 'Maintainer' },
  //   { value: 'subscriber', label: 'Subscriber' }
  // ]

  // const planOptions = [
  //   { value: '', label: 'Select Plan' },
  //   { value: 'basic', label: 'Basic' },
  //   { value: 'company', label: 'Company' },
  //   { value: 'enterprise', label: 'Enterprise' },
  //   { value: 'team', label: 'Team' }
  // ]

  // const statusOptions = [
  //   { value: '', label: 'Select Status', number: 0 },
  //   { value: 'pending', label: 'Pending', number: 1 },
  //   { value: 'active', label: 'Active', number: 2 },
  //   { value: 'inactive', label: 'Inactive', number: 3 }
  // ]

  // ** Function in get data on page change
  const handlePagination = page => {
    setLoading(true)
    dispatch(
      getData({
        order_by: sortColumn.concat(' ', sort.toUpperCase()),
        search: searchTerm,
        skip: page.selected * rowsPerPage,
        limit: rowsPerPage,
        expand_reward: true,
        expand_agency: true,
        expand_campaign: true,
        used: true
      })
    ).then(() => setLoading(false))
    setCurrentPage(page.selected + 1)
  }

  // ** Function in get data on rows per page
  const handlePerPage = e => {
    const value = parseInt(e.currentTarget.value)
    setLoading(true)
    dispatch(
      getData({
        order_by: sortColumn.concat(' ', sort.toUpperCase()),
        search: searchTerm,
        skip: (currentPage - 1) * value,
        limit: value,
        expand_reward: true,
        expand_agency: true,
        expand_campaign: true,
        used: true
      })
    ).then(() => setLoading(false))
    setRowsPerPage(value)
  }
  const timeRef = useRef()
  const handleAfterFilter = val => {
    dispatch(
      getData({
        order_by: sortColumn.concat(' ', sort.toUpperCase()),
        search: val,
        skip: 0,
        limit: rowsPerPage,
        expand_reward: true,
        expand_agency: true,
        expand_campaign: true,
        used: true
      })
    ).then(() => setLoading(false))
  }

  // ** Function in get data on search query change
  const handleFilter = val => {
    setSearchTerm(val)
    setLoading(true)
    setCurrentPage(1)
    clearTimeout(timeRef.current)
    timeRef.current = setTimeout(() => {
      handleAfterFilter(val)
    }, 500)
  }

  // ** Custom Pagination
  const CustomPagination = () => {
    const count = store.data.page_total

    return (
      <ReactPaginate
        previousLabel={''}
        nextLabel={''}
        pageCount={count || 1}
        activeClassName='active'
        forcePage={currentPage !== 0 ? currentPage - 1 : 0}
        onPageChange={page => handlePagination(page)}
        pageClassName={'page-item'}
        nextLinkClassName={'page-link'}
        nextClassName={'page-item next'}
        previousClassName={'page-item prev'}
        previousLinkClassName={'page-link'}
        pageLinkClassName={'page-link'}
        containerClassName={'pagination react-paginate justify-content-end my-2 pe-1'}
      />
    )
  }

  // ** Table data to render
  const dataToRender = () => {
    const filters = {
      status: currentStatus.value,
      q: searchTerm
    }

    const isFiltered = Object.keys(filters).some(function (k) {
      return filters[k]?.length > 0
    })

    if (store.data.data?.length > 0) {
      return store.data.data
    } else if (store.data.data?.length === 0 && isFiltered) {
      return []
    } else {
      return store.allData.data?.slice(0, rowsPerPage)
    }
  }

  const handleSort = (column, sortDirection) => {
    setSort(sortDirection)
    setSortColumn(column.sortField)
    setLoading(true)
    dispatch(
      getData({
        order_by: column.sortField.concat(' ', sortDirection.toUpperCase()),
        search: searchTerm,
        skip: (currentPage - 1) * rowsPerPage,
        limit: rowsPerPage,
        expand_reward: true,
        expand_agency: true,
        expand_campaign: true,
        used: true
      })
    ).then(() => setLoading(false))
  }

  return (
    <Fragment>
      {/* {
        false && 
        <Card>
          <CardHeader>
            <CardTitle tag='h4'>Filters</CardTitle>
          </CardHeader>
          <CardBody>
            <Row>
              <Col md='4'>
                <Label for='role-select'>Role</Label>
                <Select
                  isClearable={false}
                  value={currentRole}
                  options={roleOptions}
                  className='react-select'
                  classNamePrefix='select'
                  theme={selectThemeColors}
                  onChange={data => {
                    setCurrentRole(data)
                    dispatch(
                      getData({
                        sort,
                        sortColumn,
                        q: searchTerm,
                        role: data.value,
                        page: currentPage,
                        perPage: rowsPerPage,
                        status: currentStatus.value,
                        currentPlan: currentPlan.value
                      })
                    )
                  }}
                />
              </Col>
              <Col className='my-md-0 my-1' md='4'>
                <Label for='plan-select'>Plan</Label>
                <Select
                  theme={selectThemeColors}
                  isClearable={false}
                  className='react-select'
                  classNamePrefix='select'
                  options={planOptions}
                  value={currentPlan}
                  onChange={data => {
                    setCurrentPlan(data)
                    dispatch(
                      getData({
                        sort,
                        sortColumn,
                        q: searchTerm,
                        page: currentPage,
                        perPage: rowsPerPage,
                        role: currentRole.value,
                        currentPlan: data.value,
                        status: currentStatus.value
                      })
                    )
                  }}
                />
              </Col>
              <Col md='4'>
                <Label for='status-select'>Status</Label>
                <Select
                  theme={selectThemeColors}
                  isClearable={false}
                  className='react-select'
                  classNamePrefix='select'
                  options={statusOptions}
                  value={currentStatus}
                  onChange={data => {
                    setCurrentStatus(data)
                    if (data.number === 0) {
                      dispatch(
                        getData({
                          sort,
                          sortColumn,
                          search: searchTerm,
                          skip: (currentPage - 1) * rowsPerPage,
                          limit: rowsPerPage,
                          is_deleted: false
                        })
                      )
                    } else {
                      dispatch(
                        getData({
                          sort,
                          sortColumn,
                          search: searchTerm,
                          skip: (currentPage - 1) * rowsPerPage,
                          limit: rowsPerPage,
                          status: data.number,
                          is_deleted: false
                        })
                      )
                    }
                  }}
                />
              </Col>
            </Row>
          </CardBody>
        </Card>
      } */}
      <Card className='overflow-hidden'>
        <div className='react-dataTable'>
          <DataTable
            noHeader
            subHeader
            sortServer
            pagination
            responsive
            paginationServer
            columns={columns}
            onSort={handleSort}
            sortIcon={<ChevronDown />}
            className='react-dataTable'
            paginationComponent={CustomPagination}
            data={dataToRender()}
            subHeaderComponent={
              <CustomHeader
                store={store}
                searchTerm={searchTerm}
                rowsPerPage={rowsPerPage}
                handleFilter={handleFilter}
                handlePerPage={handlePerPage}
                toggleSidebar={toggleSidebar}
                isLoading={loading}
              />
            }
          />
        </div>
      </Card>

      <Sidebar open={sidebarOpen} toggleSidebar={toggleSidebar} />
    </Fragment>
  )
}

export default UsersList
